select
  id, user_id, user_name, phone, title, address, text, is_examine, examine_data, date, create_time, update_time
from sys_complaint


        and id = #{id}


        and user_id = #{userId}


        and user_name = #{userName}


        and phone = #{phone}


        and title = #{title}


        and address = #{address}


        and text = #{text}


        and is_examine = #{isExamine}


        and examine_data = #{examineData}


        and date = #{date}


        and create_time = #{createTime}


        and update_time = #{updateTime}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from sys_complaint


        and id = #{id}


        and user_id = #{userId}


        and user_name = #{userName}


        and phone = #{phone}


        and title = #{title}


        and address = #{address}


        and text = #{text}


        and is_examine = #{isExamine}


